{code:xml} 
<xs:complexType name="CustomException"> 
<xs:sequence> 
<xs:element name="names" nillable="true" type="tns:arrayList"/> 
</xs:sequence> 
{code} 

But it should be 
{code:xml} 
<xs:complexType name="CustomException"> 
<xs:sequence> 
<xs:element maxOccurs="unbounded" minOccurs="0" name="names" type="tns:myData"/> 
</xs:sequence> 
{code}

